mapper.select:
SELECT ep.education_id AS educationId, ep.progress_rate AS progressRate, ep.status AS status, ep.completed_at AS completedAt, COUNT(DISTINCT sc.stage_id) AS completedStages FROM education_progress ep LEFT JOIN education_stages es ON es.education_id = ep.education_id LEFT JOIN stage_completions sc ON sc.stage_id = es.id AND sc.user_id = ep.user_id WHERE ep.user_id = #{userId} AND ep.education_id IN
#{id}
GROUP BY ep.education_id, ep.progress_rate, ep.status, ep.completed_at

SELECT u.id AS userId, u.name AS userName, d.name AS departmentName, e.title AS educationTitle, ep.progress_rate AS progressRate, e.completion_criteria AS completionCriteria FROM education_progress ep JOIN users u ON u.id = ep.user_id LEFT JOIN departments d ON d.id = u.department_id JOIN educations e ON e.id = ep.education_id WHERE ep.status != 'COMPLETED'
AND ep.education_id = #{educationId}
ORDER BY ep.id ASC LIMIT #{size} OFFSET #{offset}
